#include "PlanRules.h"
#include <algorithm>
#include <cmath>
#include <map>
#include <set>
#include <queue>
#include <stdexcept>
namespace bcp {namespace {
bool near(double a,double b){return std::abs(a-b)<=numericalEpsilonMm;}
double distance(Point a,Point b){return std::hypot(a.x-b.x,a.y-b.y);}
double cross(Point a,Point b){return a.x*b.y-a.y*b.x;}
Point sub(Point a,Point b){return {a.x-b.x,a.y-b.y};}
bool on(Point p,Point a,Point b){const auto l=distance(a,b);return l>numericalEpsilonMm&&std::abs(cross(sub(p,a),sub(b,a)))/l<=numericalEpsilonMm&&p.x>=std::min(a.x,b.x)-numericalEpsilonMm&&p.x<=std::max(a.x,b.x)+numericalEpsilonMm&&p.y>=std::min(a.y,b.y)-numericalEpsilonMm&&p.y<=std::max(a.y,b.y)+numericalEpsilonMm;}
bool inside(Point p,const std::vector<Point>& polygon){bool result=false;if(polygon.size()<3)return false;for(std::size_t i=0,j=polygon.size()-1;i<polygon.size();j=i++){const auto a=polygon[i],b=polygon[j];if(on(p,a,b))return false;if((a.y>p.y)!=(b.y>p.y)&&p.x<(b.x-a.x)*(p.y-a.y)/(b.y-a.y)+a.x)result=!result;}return result;}
struct Segment {Point a,b;std::size_t wall;std::vector<Point> splits;};
struct Edge {int a,b;std::set<std::size_t> walls;};
bool insideOrOn(Point p,const std::vector<Point>& polygon){if(inside(p,polygon))return true;for(std::size_t i=0;i<polygon.size();++i)if(on(p,polygon[i],polygon[(i+1)%polygon.size()]))return true;return false;}
bool segmentInside(Point a,Point b,const std::vector<Point>& polygon){
 if(!insideOrOn(a,polygon)||!insideOrOn(b,polygon))return false;const Point delta=sub(b,a);const double squared=delta.x*delta.x+delta.y*delta.y;if(squared<=numericalEpsilonMm*numericalEpsilonMm)return false;std::vector<double> cuts{0,1};
 for(std::size_t i=0;i<polygon.size();++i){const Point p=polygon[i],q=polygon[(i+1)%polygon.size()],edge=sub(q,p);const double determinant=cross(delta,edge);if(std::abs(determinant)>1e-9){const double t=cross(sub(p,a),edge)/determinant,u=cross(sub(p,a),delta)/determinant;if(t>0&&t<1&&u>=0&&u<=1)cuts.push_back(t);}else{for(const auto v:{p,q})if(on(v,a,b))cuts.push_back(((v.x-a.x)*delta.x+(v.y-a.y)*delta.y)/squared);}}
 std::sort(cuts.begin(),cuts.end());for(std::size_t i=1;i<cuts.size();++i){if((cuts[i]-cuts[i-1])*std::sqrt(squared)<=numericalEpsilonMm)continue;const double t=(cuts[i]+cuts[i-1])/2;if(!inside({a.x+t*delta.x,a.y+t*delta.y},polygon))return false;}return true;
}
bool indoor(const std::string& text){static const std::set<std::string> names{u8"卧室",u8"厨房",u8"卫",u8"卫生间",u8"楼梯",u8"客厅",u8"餐厅",u8"玄关",u8"烤火房",u8"储物间",u8"书房",u8"堂屋",u8"棋牌室",u8"起居厅",u8"杂物间",u8"水吧",u8"公卫"};return names.count(text)!=0;}
std::vector<Point> offsetContour(std::vector<Point> polygon,double offset){
 bool changed=true;while(changed&&polygon.size()>3){changed=false;for(std::size_t i=0;i<polygon.size();++i){const auto a=polygon[(i+polygon.size()-1)%polygon.size()],b=polygon[i],c=polygon[(i+1)%polygon.size()];if(on(b,a,c)){polygon.erase(polygon.begin()+i);changed=true;break;}}}
 std::vector<Point> out;for(std::size_t i=0;i<polygon.size();++i){const auto p=polygon[i],a=polygon[(i+polygon.size()-1)%polygon.size()],b=polygon[(i+1)%polygon.size()];auto prev=sub(p,a),next=sub(b,p);const auto lp=std::hypot(prev.x,prev.y),ln=std::hypot(next.x,next.y);if(lp<=numericalEpsilonMm||ln<=numericalEpsilonMm)return {};prev={prev.x/lp,prev.y/lp};next={next.x/ln,next.y/ln};const auto determinant=cross(prev,next);if(std::abs(determinant)<1e-12)return {};const Point q0{p.x-prev.y*offset,p.y+prev.x*offset},q1{p.x-next.y*offset,p.y+next.x*offset};const auto t=cross(sub(q1,q0),next)/determinant;out.push_back({q0.x+t*prev.x,q0.y+t*prev.y});}return out;
}
}
WallTopology recogniseWalls(const Plan& plan){
 WallTopology result;if(plan.rooms.empty())return result;std::vector<Segment> segments;
 for(std::size_t i=0;i<plan.walls.size();++i){const auto& w=plan.walls[i];if(!near(w.left+w.right,plan.majorWallThickness)||distance(w.start,w.end)<=numericalEpsilonMm)continue;const auto a=bodyCentreStart(w);const Point b{a.x+w.end.x-w.start.x,a.y+w.end.y-w.start.y};if(!near(a.x,b.x)&&!near(a.y,b.y))continue;segments.push_back({a,b,i,{a,b}});}
 for(std::size_t i=0;i<segments.size();++i)for(std::size_t j=i+1;j<segments.size();++j){auto& a=segments[i];auto& b=segments[j];for(const auto p:{a.a,a.b})if(on(p,b.a,b.b))b.splits.push_back(p);for(const auto p:{b.a,b.b})if(on(p,a.a,a.b))a.splits.push_back(p);const bool av=near(a.a.x,a.b.x),bv=near(b.a.x,b.b.x);if(av!=bv){const Point p{av?a.a.x:b.a.x,av?b.a.y:a.a.y};if(on(p,a.a,a.b)&&on(p,b.a,b.b)){a.splits.push_back(p);b.splits.push_back(p);}}}
 std::vector<Point> nodes;std::vector<Edge> edges;std::map<std::pair<int,int>,std::size_t> edgeIndex;const auto node=[&](Point p){for(std::size_t i=0;i<nodes.size();++i)if(distance(nodes[i],p)<=numericalEpsilonMm)return static_cast<int>(i);nodes.push_back(p);return static_cast<int>(nodes.size()-1);};
 for(auto& segment:segments){std::sort(segment.splits.begin(),segment.splits.end(),[&](Point a,Point b){return distance(a,segment.a)<distance(b,segment.a);});segment.splits.erase(std::unique(segment.splits.begin(),segment.splits.end(),[](Point a,Point b){return distance(a,b)<=numericalEpsilonMm;}),segment.splits.end());for(std::size_t i=1;i<segment.splits.size();++i){int a=node(segment.splits[i-1]),b=node(segment.splits[i]);if(a==b)continue;if(a>b)std::swap(a,b);const auto key=std::make_pair(a,b);auto it=edgeIndex.find(key);if(it==edgeIndex.end()){edgeIndex[key]=edges.size();edges.push_back({a,b,{segment.wall}});}else edges[it->second].walls.insert(segment.wall);}}
 std::vector<std::vector<int>> neighbours(nodes.size());for(const auto& edge:edges){neighbours[edge.a].push_back(edge.b);neighbours[edge.b].push_back(edge.a);}for(std::size_t i=0;i<nodes.size();++i)std::sort(neighbours[i].begin(),neighbours[i].end(),[&](int a,int b){return std::atan2(nodes[a].y-nodes[i].y,nodes[a].x-nodes[i].x)<std::atan2(nodes[b].y-nodes[i].y,nodes[b].x-nodes[i].x);});
 std::vector<int> component(nodes.size(),-1);int components=0;for(std::size_t i=0;i<nodes.size();++i)if(component[i]<0){std::queue<int> todo;todo.push(static_cast<int>(i));component[i]=components;while(!todo.empty()){const int v=todo.front();todo.pop();for(const int n:neighbours[v])if(component[n]<0){component[n]=components;todo.push(n);}}++components;}
 std::map<std::pair<int,int>,std::size_t> faceOf;std::vector<std::vector<std::pair<int,int>>> walks;std::vector<int> faceComponents;std::vector<bool> hasIndoor,hasCourt,hasLandscape;
 for(const auto& edge:edges)for(const auto initial:{std::make_pair(edge.a,edge.b),std::make_pair(edge.b,edge.a)}){if(faceOf.count(initial))continue;auto current=initial;Region face;face.id=result.regions.size();std::vector<std::pair<int,int>> walk;do{if(faceOf.count(current))throw std::runtime_error("wall topology half-edge traversal conflict");faceOf[current]=face.id;walk.push_back(current);face.boundary.push_back(nodes[current.first]);const auto& list=neighbours[current.second];const auto it=std::find(list.begin(),list.end(),current.first);if(it==list.end()||list.empty())throw std::runtime_error("wall topology missing twin");const auto index=static_cast<std::size_t>(it-list.begin());current={current.second,list[(index+list.size()-1)%list.size()]};if(walk.size()>edges.size()*2+1)throw std::runtime_error("wall topology traversal limit");}while(current!=initial);
  for(std::size_t i=0;i<face.boundary.size();++i)face.area+=cross(face.boundary[i],face.boundary[(i+1)%face.boundary.size()])/2;
  bool in=false,court=false,other=false,landscape=false;if(face.area>numericalEpsilonMm){for(const auto& room:plan.rooms){const Point centre{(room.min.x+room.max.x)/2,(room.min.y+room.max.y)/2};if(!inside(centre,face.boundary))continue;if(indoor(room.text)){in=true;face.labels.push_back(room.handle);}else if(room.text==u8"庭院"){court=true;face.labels.push_back(room.handle);}else if(room.text==u8"花池"){landscape=true;other=true;face.labels.push_back(room.handle);}else if(room.text==u8"门廊"||room.text==u8"走廊"||room.text==u8"花池"){other=true;face.labels.push_back(room.handle);}}}
  hasLandscape.push_back(landscape);face.kind=landscape?"landscape":face.area<=numericalEpsilonMm?"unbounded-or-degenerate":in&&!court&&!other?"indoor":court&&!in?"courtyard":in||court?"mixed":"unknown";faceComponents.push_back(component[initial.first]);hasIndoor.push_back(in);hasCourt.push_back(court);walks.push_back(std::move(walk));result.regions.push_back(std::move(face));
 }
 std::vector<bool> main(components,false),openExterior(components,false);for(std::size_t i=0;i<result.regions.size();++i)if(result.regions[i].area>numericalEpsilonMm&&hasIndoor[i])main[faceComponents[i]]=true;
 std::vector<std::set<std::size_t>> wallFaces(plan.walls.size());std::vector<bool> wallExterior(plan.walls.size(),false),wallMajor(plan.walls.size(),false);
 for(const auto& edge:edges){const auto left=faceOf.at({edge.a,edge.b}),right=faceOf.at({edge.b,edge.a});const int comp=component[edge.a];if(left==right){if(result.regions[left].area<=numericalEpsilonMm)openExterior[comp]=true;continue;}if(!main[comp])continue;const auto qualified=[&](std::size_t f){return result.regions[f].area>numericalEpsilonMm&&!hasLandscape[f];};if(!qualified(left)&&!qualified(right))continue;const bool external=!qualified(left)||!qualified(right);const bool yard=(result.regions[left].kind=="courtyard"||result.regions[right].kind=="courtyard");const bool supported=external||hasIndoor[left]||hasIndoor[right]||hasCourt[left]||hasCourt[right];if(!supported)continue;for(const auto wall:edge.walls){wallFaces[wall].insert(left);wallFaces[wall].insert(right);wallExterior[wall]=wallExterior[wall]||external||yard;wallMajor[wall]=true;}}
 for(std::size_t i=0;i<plan.walls.size();++i){const auto& wall=plan.walls[i];WallRecognition recognition;recognition.handle=wall.handle;if(wallMajor[i]){recognition.role=wallExterior[i]?WallRole::exterior:WallRole::majorBoundary;recognition.faces.assign(wallFaces[i].begin(),wallFaces[i].end());}else if(near(wall.left+wall.right,plan.partitionWallThickness)&&distance(wall.start,wall.end)>numericalEpsilonMm){const auto a=bodyCentreStart(wall);const Point b{a.x+wall.end.x-wall.start.x,a.y+wall.end.y-wall.start.y};for(const auto& face:result.regions)if(face.kind=="indoor"&&segmentInside(a,b,face.boundary)){recognition.role=WallRole::interiorPartition;recognition.faces.push_back(face.id);break;}}result.walls.push_back(std::move(recognition));}
 std::set<std::pair<int,int>> boundary,visited;const auto buildingFace=[&](std::size_t f){return result.regions[f].area>numericalEpsilonMm&&main[faceComponents[f]]&&!hasLandscape[f]&&!openExterior[faceComponents[f]];};
 for(const auto& edge:edges){const bool left=buildingFace(faceOf.at({edge.a,edge.b})),right=buildingFace(faceOf.at({edge.b,edge.a}));if(left!=right)boundary.insert(left?std::make_pair(edge.b,edge.a):std::make_pair(edge.a,edge.b));}
 for(const auto initial:boundary){if(visited.count(initial))continue;std::vector<Point> polygon;auto current=initial;bool closed=false;for(std::size_t n=0;n<=boundary.size();++n){if(!visited.insert(current).second)break;polygon.push_back(nodes[current.first]);const auto& choices=neighbours[current.second];const auto it=std::find(choices.begin(),choices.end(),current.first);if(it==choices.end())break;const auto index=static_cast<std::size_t>(it-choices.begin());bool found=false;for(std::size_t k=1;k<=choices.size();++k){const auto next=std::make_pair(current.second,choices[(index+choices.size()-k)%choices.size()]);if(boundary.count(next)){current=next;found=true;break;}}if(!found)break;if(current==initial){closed=true;break;}}double area=0;for(std::size_t i=0;i<polygon.size();++i)area+=cross(polygon[i],polygon[(i+1)%polygon.size()])/2;if(closed&&area<-numericalEpsilonMm){auto contour=offsetContour(std::move(polygon),plan.majorWallThickness/2);if(!contour.empty())result.outerBodyContours.push_back(std::move(contour));}}

 return result;
}
}
